3296],[-46.851258,-22.428164],[-46.854145,-22.426732],[-46.855138,-22.42605],[-46.854472,-22.424309]]]]}$q$), 4326), $q${"regra_id":"itapira_area_urbana_6_30_a_12m","municipio":"Itapira","ibge":"3522604","uf":"SP","tipo":"zona","regime":"Área urbana (6,30–12 m)","nome":"Itapira: área urbana — veículos de carga de 6,30 m a 12 m só circulam das 7h às 9h e das 18h às 20h","status":"ativa","confianca":"media","janelas":[{"days":[1,2,3,4,5,6,7],"from":"00:00","to":"07:00"},{"days":[1,2,3,4,5,6,7],"from":"09:00","to":"18:00"},{"days":[1,2,3,4,5,6,7],"from":"20:00","to":"24:00"}],"feriados":"aplica","alvo":{"caminhao":true,"todas":[{"campo":"comprimento_m","acima":6.3},{"campo":"comprimento_m","ate":12}]},"origem_destino_dentro":"avisa","autorizacao":"Autorização Especial de Circulação e Estacionamento (arts. 6º e 7º), válida só no horário do art. 3º","excecoes":["Art. 4º: veículos do art. 29, VII e VIII, do CTB","Art. 5º, I: VUC até 6,30 m x 2,20 m; art. 5º, II: veículos de autoescola em aula","Art. 6º: concretagem, mudanças, perecíveis e imprensa com Autorização Especial, no horário do art. 3º"],"base_legal":[{"ato":"Lei municipal 5.066, de 25/04/2013 (Itapira) — publicada em 26/04/2013","artigo":"art. 3º (circulação de veículo de carga com comprimento entre 6,30 m e 12 m na área urbana permitida das 7h às 9h e das 18h às 20h), arts. 4º a 6º (exceções)","url":"https://itapira.sp.gov.br/legislacao/5066-13.pdf"}],"nota":"Confiança média: a redação do art. 3º ('Estará permitida a circulação ... nos seguintes horários') limita os caminhões de 6,30 a 12 m a 4 h/dia na área urbana, todos os dias (a lei não fala em dias úteis nem excetua feriados); o art. 6º confirma a leitura. Sem notícia de fiscalização e sem perímetro no ato (mesma zona aproximada da regra de 12 m). As janelas são o complemento de 7h–9h e 18h–20h. A LC 5.392/2015 (PlanMob) fala em zonas de restrição 'a instituir', sem revogar a lei.","fonte_geometria":"IBGE (setores censitários urbanos do distrito-sede, Censo 2022), sem a SP-147 e a SP-352 (OSM, ODbL): aproximação da área urbana","vigencia_inicio":"2013-04-26","vuc":{"largura_max_m":2.2,"comprimento_max_m":6.3,"exige_cadastro":false,"orgao":"Departamento de Trânsito, Transportes e Posturas","artigo":"Lei 5.066/2013, art. 5º, I (VUC: comprimento máximo 6,30 m e largura máxima 2,20 m, excluído das restrições de circulação)"},"descricao":"Área urbana de Itapira (sede), aproximada pelos setores censitários urbanos do distrito-sede (IBGE 2022), sem as rodovias SP-147 e SP-352","aproximado":true,"setores_ibge":123,"verificado_em":"2026-10-11"}$q$::jsonb, $q$2013-04-26$q$::timestamptz, null::timestamptz)
insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$itapira$q$, $q$https://itapira.sp.gov.br/legislacao/5066-13.pdf (Lei 5.066/2013) ; https://itapira.sp.gov.br/legislacao/089-13.pdf (Decreto 089/2013)$q$, $q$Atos oficiais de Itapira: domínio público (Lei 9.610/1998 art. 8º IV). Zona: IBGE, Malha de Setores Censitários do Censo 2022 (dados públicos, citar a fonte: IBGE), com as rodovias recortadas sobre o OpenStreetMap (ODbL 1.0, © colaboradores do OSM).$q$, 2, $q$Lei 5.066/2013: veículos de carga acima de 12 m proibidos na área urbana (art. 2º; rotas do Decreto 089/2013 para os locais comerciais e industriais); de 6,30 m a 12 m só circulam das 7h às 9h e das 18h às 20h (art. 3º); VUC até 6,30 m x 2,20 m isento (art. 5º, I). A 'área urbana' não é delimitada no ato: aproximada pelos setores censitários urbanos do IBGE 2022 do distrito-sede, sem a SP-147 e a SP-352.$q$);
